INSERT INTO "events" ("id","title","category_id","color_override","start","end","rrule","exdates","description","steps","location","contact_name","contact_phone","notion_url","source","caldav_uid","caldav_url","caldav_etag","created_at","updated_at") VALUES(52,'Sintra - Private Tour',NULL,NULL,'2026-08-06T08:30:00','2026-08-06T16:55:00',NULL,NULL,replace('----------------------- TOUR CONFIRMATION VOUCHER: -----------------------\n\n👤 Name: Angela Zaltsman\n👥 Number: 2 Adults, 1 Student, 1 Child (age 12) [Total 4 people]\n📱 Phone: +1-CA 416-721-7444\n🗺️ Tour: Sintra Full-Day Private Driving & Walking Tour\n🧑‍🏫 Guide: Liliana\n📅 Date: Thursday, August 6, 2026, at 8:30am\n🕐 Time: 8:30am to 4:30pm\n🏨 Accommodations: Salitre Luxury Apartment, Rua do Salitre 100, 1250-191, Lisbon\n📍 Meeting Point: Pickup at your apartment, Rua do Salitre 100, Lisbon\n🏁 Ending Point: Your apartment in Lisbon, or another location in Lisbon if you prefer\n\nPRICES & PAYMENTS:\n💰 Total: €579. The price is a total, not per person.\n💳 -Deposit: €134 (PAID). Your deposit charges will appear as "AMIRA Travel Tours."\n🧾 Balance due: €445. Payable to the guide in Mastercard, Visa card, or cash (EUR) at the end of the tour.\n\nADDITIONAL FEES:\nEntry ticket fees: €40 per person, paid in cash or by credit card.\nPlease don''t buy entry tickets in advance. We will purchase your tickets in advance.\nTicket fees for Sintra tours are non-refundable once the tour is reserved.\n\nMEETING POINT INFO:\nMeeting Point Address:\nPickup at your apartment, Rua do Salitre 100, Lisbon\n\nPLEASE REMEMBER:\n• Confirm you''re with the correct guide — other tours operate in the same area, so ensure you''re with your Lisbon Explorer guide.\n• Wear comfortable, athletic shoes — Portugal''s cobblestone streets are difficult to navigate in dress shoes.\n• Check the weather before departing, especially in the cooler months—bring an umbrella or a raincoat if it''s overcast.\n• Tours depart on time, rain or shine. Our guides often have post-tour appointments and cannot extend the tour time if you are delayed.\n• Need help before the tour? Call our hotline immediately. (See below).\n• Force majeure notice: Circumstances beyond our control (extreme weather, natural disasters, protests, pandemics) may affect your tour. By reserving, guests confirm they have made contingency arrangements in the event of a cancellation.\n\nHOTLINE PHONE IN CASE YOU ARE DELAYED OR CAN NOT FIND THE GUIDE:\nFrom a US or Canada-based phone:\nStep 1: Dial 011 (International access code). From a mobile phone while in Europe, dial 00 or insert a + instead (by holding the 0 key)\nStep 2: Dial 351 (Portuguese country code)\nStep 3: Dial 969.219.059 (International rates may apply)\n\nFrom a Portugal-based phone: Dial 969.219.059\n\nCANCELLATIONS:\nAt the bottom of this message, you will see OUR CANCELLATION POLICY BASICS.\nPlease review our Terms & Conditions page on our website for more details.\nBy submitting the deposit payment, you agree to this Tour Confirmation and affirm that there are no errors or corrections. You also agree to our Flexible Cancellation Policy and Extended Terms and Conditions on our website.\n\nIn the meantime, feel free to call or write if you have other questions about your trip to Lisbon.\n\nPlease reply with an "OK" so we know you have these important details.\nWe look forward to sharing the City of Explorers with you soon.\n\n\nObrigado,\nDavide\n\n','\n',char(10)),NULL,NULL,NULL,NULL,NULL,'caldav','6CA5B9F8-6CAA-4167-A6C2-7C6B3FB79E41','https://caldav.icloud.com/17547000382/calendars/26a6396ca5a64432663403c69bf1de49f8e42615f33db07879e03ae2cff6f4cb/6CA5B9F8-6CAA-4167-A6C2-7C6B3FB79E41.ics','"mqh6gc88"','2026-07-31 18:00:19','2026-08-03 12:30:13');
