INSERT INTO "events" ("id","title","category_id","color_override","start","end","rrule","exdates","description","steps","location","contact_name","contact_phone","notion_url","source","caldav_uid","caldav_url","caldav_etag","created_at","updated_at") VALUES(59,'Jewish Quarter - tour',NULL,NULL,'2026-08-07T10:00:00','2026-08-07T13:00:00',NULL,NULL,replace('----------------------- TOUR CONFIRMATION VOUCHER: -----------------------\n\n👤 Name: Angela Zaltsman\n👥 Number: 2 Adults, 1 Student, 1 Child [Total 4 people] (+9 Others)\n📱 Phone: +1 416-721-7444\n🗺️ Tour: Jewish Lisbon SEMI-Private Shared Walking Tour\n🧑‍🏫 Guide: Paolo\n📅 Date: Friday, August 7, 2026, at 10:00am\n🕐 Time: 10:00am to 1:30pm\n🏨 Accommodations: Salitre Luxury Apartment, Rua do Salitre 100, Lisbon\n📍 Meeting Point: The Café Quiosque Oliveira, Praça do Príncipe Real 36, Lisbon\n🏁 Ending Point: Rossio Square (Praça de D. Pedro IV)\n\nPRICES & PAYMENTS:\n💰 Total: €194 for 1 to 2 total participants, / €292 for 3 to 6 total participants, / €480 for 7 to 12 total participants.\n💳 -Deposit: €60 (PAID). Your deposit charges will appear as "AMIRA Travel Tours."\n🧾 Balance due: Payable only in cash (EUR) is split equally among all participants.\n\nADDITIONAL FEES:\nEntry ticket fees: €7 per adult, €5 per student and senior +65 years. Children up to 14 years have no entry fee. Payable with cash or by credit card upon entry.\n\nMEETING POINT INFO:\n• A map and a photo of the easy-to-find tour meeting point are at the end of this message.\n• There are several Quiosques (Kiosks) on one block in Lisbon. Please go to the Meeting Point Address provided below.\n• Taxis or Uber are faster and more affordable than public transit to the meeting point in Principe Real, which is atop a steep hill.\n• If you are arriving by rental car, park at Parque Largo do Rato Telpark by Empark, and walk 10 minutes to the tour meeting point.\n\nMeeting Point Address:\nThe Café Quiosque Oliveira, Praça do Príncipe Real 36, Lisbon\nAcross the street, you will see your guide on the corner in front of The Cafe Quiosque Oliveira, holding a blue folder.\n\n\nPLEASE REMEMBER:\n• Confirm you''re with the correct guide — other tours operate in the same area, so ensure you''re with your Lisbon Explorer guide.\n• Wear comfortable, athletic shoes — Portugal''s cobblestone streets are difficult to navigate in dress shoes.\n• Check the weather before departing, especially in the cooler months—bring an umbrella or a raincoat if it''s overcast.\n• Tours depart on time, rain or shine. Our guides often have post-tour appointments and cannot extend the tour time if you are delayed.\n• Need help before the tour? Call our hotline immediately. (See below).\n• Force majeure notice: Circumstances beyond our control (extreme weather, natural disasters, protests, pandemics) may affect your tour. By reserving, guests confirm they have made contingency arrangements in the event of a cancellation.\n\nHOTLINE PHONE IN CASE YOU ARE DELAYED OR CAN NOT FIND THE GUIDE:\nFrom a US or Canada-based phone:\nStep 1: Dial 011 (International access code). From a mobile phone while in Europe, dial 00 or insert a + instead (by holding the 0 key)\nStep 2: Dial 351 (Portuguese country code)\nStep 3: Dial 969.219.059 (International rates may apply)\n\nFrom a Portugal-based phone: Dial 969.219.059\n\nCANCELLATIONS:\nAt the bottom of this message, you will see OUR CANCELLATION POLICY BASICS.\nPlease review our Terms & Conditions page on our website for more details.\nBy submitting the deposit payment, you agree to this Tour Confirmation and affirm that there are no errors or corrections. You also agree to our Flexible Cancellation Policy and Extended Terms and Conditions on our website.\n\nMEETING POINT MAP & PHOTO:\nMeeting Point Map\n\nMeeting Point Photo\n\nIn the meantime, feel free to call or write if you have other questions about your trip to Lisbon.\n\nPlease reply with an "OK" so we know you have these important details.\nWe look forward to sharing the City of Explorers with you soon.\n\n\nObrigado,\nDavide\n\nWebsite: www.LisbonExplorer.com\nhttps://www.lisbonexplorer.com/index.html\n\nhttps://icontours.com/Email%20Signature%20Logos/Icon%20Instagram%20Logo.png  https://x.com/AccountMai91620   https://www.youtube.com/channel/UCPZMwNR_Pw4Z-br8J8QP6jw   https://www.facebook.com/LisbonExplorer/\n\nTo ensure email delivery, add info@lisbonexplorer.com to your address book, contacts, or safe sender list.\n','\n',char(10)),NULL,NULL,NULL,NULL,NULL,'caldav','BEEABBB1-3DA3-482A-8EBA-928C930D0516','https://caldav.icloud.com/17547000382/calendars/26a6396ca5a64432663403c69bf1de49f8e42615f33db07879e03ae2cff6f4cb/BEEABBB1-3DA3-482A-8EBA-928C930D0516.ics','"mqh6mkmr"','2026-07-31 18:00:21','2026-08-03 12:30:14');
